type StopInput = Partial<GuideStop> & { id: string; name: string; neighborhood: string; coordinates: [number, number]; description: string; officialUrl: string; photo?: string; editorialUrls?: string[] };

function stop(input: StopInput): GuideStop {
  const { id, name, neighborhood, coordinates, description, officialUrl, bookingUrl, photo: suppliedPhoto, editorialUrls = [], sourceUrls: extraSourceUrls = [], sourceEvidence, ...rest } = input;
  const photo = curatedPhotos[id] ?? suppliedPhoto ?? commons(`${name} Buenos Aires.jpg`);
  const mapUrl = sourceEvidence?.mapUrl ?? maps(`${name} Buenos Aires Argentina`);
  return {
    id, poiId: input.poiId ?? `buenos-aires-venue-${id.replace(/^buenos-aires-/, "")}`, name, coordinates, description, subcategory: neighborhood,
    photo, imageSourceUrl: photo, imageSourceName: photo.includes("wikimedia") ? "Wikimedia Commons source candidate" : "Venue-specific sourced image",
    officialUrl, ...(bookingUrl ? { bookingUrl } : {}),
    sourceUrls: [...new Set([officialUrl, bookingUrl, mapUrl, photo, ...editorialUrls, ...extraSourceUrls].filter(Boolean) as string[])],
    sourceEvidence: { officialUrl, mapUrl, currentStatusUrl: mapUrl, imageSourceUrl: photo, editorialUrls, checkedAt, notes: "The official venue, property, museum, booking, tourism, or government source and a current map listing were checked; no permanent-closure notice was found.", ...sourceEvidence },
    ...rest,
  };
}

